import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"GRID+","description":"","frontmatter":{"title":"GRID+","type":"framework"},"headers":[],"relativePath":"frameworks/grid-plus/index.md","filePath":"frameworks/grid-plus/index.md"}'),o={name:"frameworks/grid-plus/index.md"};function n(s,e,d,l,p,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="grid-a-structured-framework-for-multi-dimensional-research-evaluation" tabindex="-1">GRID+: a structured framework for multi-dimensional research evaluation <a class="header-anchor" href="#grid-a-structured-framework-for-multi-dimensional-research-evaluation" aria-label="Permalink to &quot;GRID+: a structured framework for multi-dimensional research evaluation&quot;">​</a></h1><p>A framework for transforming qualitative prompts into structured, repeatable evaluation pipelines.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>GRID+ addresses the instability and opacity of prompt-based evaluation using large language models. Prompt-driven assessments are often difficult to reproduce, compare, or audit, and can be highly sensitive to phrasing and context. Existing evaluation approaches tend to rely either on rigid quantitative indicators or on loosely specified qualitative judgement. GRID+ is designed as a middle layer between these extremes: a structured, multi-dimensional framework that preserves interpretability while improving consistency and reuse.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Description</th></tr></thead><tbody><tr><td>G</td><td>General characteristics of the research output, such as scope, type, or positioning</td></tr><tr><td>R</td><td>Research quality and rigour, including methods, validity, and robustness</td></tr><tr><td>I</td><td>Influence or impact, including scholarly, societal, or translational reach</td></tr><tr><td>D</td><td>Directionality or novelty, including originality, risk, or divergence from existing work</td></tr><tr><td>+</td><td>Extension layer for context-specific dimensions, adjustments, or refinements</td></tr></tbody></table><p>The framework is modular. The four core dimensions provide a baseline structure, while the extension layer allows adaptation to domain, dataset, or evaluation objective.</p><h2 id="from-prompt-to-pipeline" tabindex="-1">From prompt to pipeline <a class="header-anchor" href="#from-prompt-to-pipeline" aria-label="Permalink to &quot;From prompt to pipeline&quot;">​</a></h2><p>GRID+ formalises a shift from single, unstructured prompts to decomposed evaluation workflows. Rather than asking a model to produce a holistic judgement in one step, evaluation is distributed across explicit dimensions, each treated as a separate analytical operation. This creates a pipeline in which reasoning is segmented, outputs are structured, and intermediate assessments can be inspected, compared, and reused. The result is a system that is less sensitive to prompt variation and better suited to reproducible evaluation.</p><h2 id="how-it-is-applied" tabindex="-1">How it is applied <a class="header-anchor" href="#how-it-is-applied" aria-label="Permalink to &quot;How it is applied&quot;">​</a></h2><p>Application follows a staged process. A set of research outputs is first selected, such as publications, projects, or other research artefacts. Each output is then assessed across the GRID+ dimensions using prompts or instructions defined for each dimension rather than for the object as a whole. The results are captured in a structured format, producing a multi-dimensional profile for each item. These profiles can then be compared, aggregated, or analysed further depending on the evaluation objective.</p><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Output</th><th>G</th><th>R</th><th>I</th><th>D</th></tr></thead><tbody><tr><td>Paper A</td><td>Broad interdisciplinary scope</td><td>Strong methodological clarity</td><td>Moderate citation uptake</td><td>High conceptual novelty</td></tr><tr><td>Paper B</td><td>Narrow domain focus</td><td>Moderate rigour</td><td>High policy relevance</td><td>Low novelty</td></tr></tbody></table><p>This example is simplified and does not represent full implementation.</p><h2 id="interpretation" tabindex="-1">Interpretation <a class="header-anchor" href="#interpretation" aria-label="Permalink to &quot;Interpretation&quot;">​</a></h2><p>GRID+ outputs are inherently multi-dimensional. They are not intended to be collapsed into a single composite score. Instead, they support comparative reasoning across dimensions, making differences in profile explicit, such as high novelty with limited uptake, or strong influence with lower originality. This allows evaluation to remain differentiated rather than flattened into aggregate indicators.</p><h2 id="scope-and-limits" tabindex="-1">Scope and limits <a class="header-anchor" href="#scope-and-limits" aria-label="Permalink to &quot;Scope and limits&quot;">​</a></h2><p>The framework depends on the quality and completeness of the underlying data. Dimension definitions introduce an element of interpretation, especially for concepts such as novelty, influence, or directionality. Results may not transfer directly across domains without adaptation through the extension layer. Decomposing evaluation into dimensions improves clarity, but it can also reduce coherence if interactions between dimensions are ignored.</p><h2 id="implementation-status" tabindex="-1">Implementation status <a class="header-anchor" href="#implementation-status" aria-label="Permalink to &quot;Implementation status&quot;">​</a></h2><p>Full scoring logic, pipelines, and operational details are not public.</p><h2 id="related-work" tabindex="-1">Related work <a class="header-anchor" href="#related-work" aria-label="Permalink to &quot;Related work&quot;">​</a></h2><p>GRID+ is related to broader efforts to structure LLM-based reasoning into explicit workflows rather than single prompts. It also connects to work on AI-assisted metascience, evaluation systems, and validation tools such as AVA, where assessment is decomposed into inspectable stages.</p><h2 id="depth" tabindex="-1">Depth <a class="header-anchor" href="#depth" aria-label="Permalink to &quot;Depth&quot;">​</a></h2><ul><li>overview: available</li><li>methodological detail: partial</li><li>full protocol and implementation: not public</li></ul>',24)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
